<!-- @FIGURE_UI_BEGIN -->
<label>Band gap size: <output id="bandGapSizeVal">1.5</output><input id="bandGapSizeInput" type="range" min="0" max="4" step="0.1" value="1.5" oninput="document.getElementById('bandGapSizeVal').value=this.value;update_bandGapSize(+this.value)"></label><button onclick="trigger_promoteElectron()">Promote electron</button><span id="demoNarration" style="display:block;margin:0;font-size:10px;max-width:180px">The valence band is filled below and the conduction band is above it. With a moderate band gap, some electrons can be promoted under suitable conditions, so the material is labeled as a semiconductor.</span><span style="display:flex;gap:4px;align-items:center"><button onclick="prevStep()">◀</button><span id="stepLabel"></span><button onclick="nextStep()">▶</button></span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 900, H = 360;
draw.viewbox(0, 0, W, H);

var green = '#bdd58a';
var violet = '#aab3d8';
var ink = '#000000';
var guide = '#666666';
var electronBlue = '#1c77c3';
var energyGold = '#f6c343';
var failRed = '#d95f5f';

var state = {
  selected: 1,
  gap: 1.5,
  lastPromotion: false,
  step: 0
};

var panels = [
  { x: 90,  title: 'Insulator',      gap: 3.5, dynamic: false },
  { x: 360, title: 'Semiconductor',  gap: 1.5, dynamic: true  },
  { x: 630, title: 'Conductor',      gap: 0.1, dynamic: false }
];

var bandW = 190;
var bandH = 76;
var valenceY = 275;
var gapScale = 39;
var minGapPx = 2;
var panelGroups = [];
var promotionLayer = draw.group();
var labelsLayer = draw.group();

function categoryFromGap(g) {
  if (g <= 0.35) return 'Conductor';
  if (g < 2.35) return 'Semiconductor';
  return 'Insulator';
}

function conductionYForGap(g) {
  return valenceY - Math.max(minGapPx, g * gapScale) - bandH;
}

function gapPixels(g) {
  return valenceY - (conductionYForGap(g) + bandH);
}

function clearGroup(g) {
  if (g) g.clear();
}

function addTextWithHalo(parent, txt, x, y, size, weight, anchor) {
  return parent.text(txt)
    .font({ family: 'Arial, Helvetica, sans-serif', size: size, weight: weight || 'normal', anchor: anchor || 'middle' })
    .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' })
    .fill(ink)
    .move(x, y);
}

function drawArrowLine(parent, x, y1, y2, color, width, doubleHead) {
  var line = parent.line(x, y1, x, y2).stroke({ color: color, width: width, linecap: 'round' });
  var ah = 8, aw = 5;
  if (y2 >= y1) {
    parent.polygon([[x, y2], [x - aw, y2 - ah], [x + aw, y2 - ah]]).fill(color).stroke('none');
    if (doubleHead) parent.polygon([[x, y1], [x - aw, y1 + ah], [x + aw, y1 + ah]]).fill(color).stroke('none');
  } else {
    parent.polygon([[x, y2], [x - aw, y2 + ah], [x + aw, y2 + ah]]).fill(color).stroke('none');
    if (doubleHead) parent.polygon([[x, y1], [x - aw, y1 - ah], [x + aw, y1 - ah]]).fill(color).stroke('none');
  }
  return line;
}

function panelGapValue(i) {
  return panels[i].dynamic ? state.gap : panels[i].gap;
}

function panelTitle(i) {
  return panels[i].dynamic ? categoryFromGap(state.gap) : panels[i].title;
}

function renderPanels() {
  promotionLayer.clear();
  labelsLayer.clear();
  panelGroups.forEach(function (g) { g.remove(); });
  panelGroups = [];

  panels.forEach(function (p, i) {
    var g = draw.group();
    panelGroups.push(g);

    var gap = panelGapValue(i);
    var cY = conductionYForGap(g);
    var actualGap = gapPixels(g);
    var x = p.x;
    var selected = (i === state.selected);

    var hit = g.rect(bandW + 52, 310).move(x - 26, 20).fill({ color: '#fff', opacity: 0 });
    hit.css('cursor', 'pointer')
      .on('mousemove', function (e) {
        showTooltip('Click to select this material and test whether an electron can cross its band gap.', e);
      })
      .on('mouseleave', function () { hideTooltip(); })
      .on('click', function () {
        state.selected = i;
        trigger_promoteElectron();
        renderPanels();
      });

    if (selected) {
      g.rect(bandW + 26, 318).move(x - 13, 16).radius(8).fill('none').stroke({ color: '#4a90e2', width: 2, dasharray: '6 5' });
    }

    addTextWithHalo(g, panelTitle(i), x + bandW / 2, 8, 25, 'bold', 'middle');

    g.rect(bandW, bandH).move(x, cY).fill(green).stroke('none');
    g.rect(bandW, bandH).move(x, valenceY).fill(violet).stroke('none');

    addTextWithHalo(g, 'Conduction', x + bandW / 2, cY + 21, 25, 'normal', 'middle');
    addTextWithHalo(g, 'Valence', x + bandW / 2, valenceY + 22, 25, 'normal', 'middle');

    g.line(x, cY + bandH, x, valenceY).stroke({ color: guide, width: 2, dasharray: '8 9' });
    g.line(x + bandW, cY + bandH, x + bandW, valenceY).stroke({ color: guide, width: 2, dasharray: '8 9' });

    if (actualGap > 14) {
      var ax = x + 48;
      drawArrowLine(g, ax, cY + bandH + 3, valenceY - 3, ink, 2.2, true);
      addTextWithHalo(g, 'Band gap', ax + 8, cY + bandH + actualGap / 2 - 14, 25, 'normal', 'start');
    } else {
      g.line(x, valenceY, x + bandW, valenceY).stroke({ color: '#ffffff', width: 3 });
      addTextWithHalo(g, 'Band gap', x + bandW + 13, valenceY - 16, 25, 'normal', 'start');
    }

    if (selected) {
      var ex = x + bandW / 2 - 34;
      var ey = valenceY + bandH / 2;
      g.circle(14).center(ex, ey).fill(electronBlue).stroke({ color: '#fff', width: 2 });
      addTextWithHalo(g, 'e⁻', ex + 18, ey - 17, 16, 'bold', 'start');

      var enough = gap <= 1.65;
      var targetY = enough ? cY + bandH / 2 : Math.max(cY + bandH + 12, valenceY - 36);
      var arr = drawArrowLine(g, ex + 32, ey - 4, targetY, enough ? energyGold : failRed, 3, false);
      arr.attr({ opacity: enough ? 0.95 : 0.55 });
      g.circle(enough ? 18 : 12).center(ex + 32, targetY).fill({ color: enough ? energyGold : failRed, opacity: enough ? 0.32 : 0.22 }).stroke('none');

      var note = enough ? 'enough energy' : 'not enough';
      var noteX = x + bandW / 2 + 35;
      var noteY = Math.max(56, Math.min(valenceY - 18, (ey + targetY) / 2 - 18));
      var bg = g.rect(120, 24).move(noteX - 8, noteY - 2).radius(4).fill({ color: '#fff', opacity: 0.78 }).stroke('none');
      addTextWithHalo(g, note, noteX, noteY, 15, 'bold', 'start');
      bg.back();

      if (enough && state.lastPromotion) {
        g.circle(12).center(ex + 32, cY + bandH / 2).fill(electronBlue).stroke({ color: '#fff', width: 2 });
      }
    }
  });
}

function update_bandGapSize(v) {
  state.gap = v;
  panels[1].dynamic = true;
  state.selected = 1;
  state.lastPromotion = false;
  renderPanels();
}

function trigger_promoteElectron() {
  var g = panelGapValue(state.selected);
  state.lastPromotion = true;
  renderPanels();
  var cat = categoryFromGap(g);
  var ok = g <= 1.65;
  showPopup(
    'Electron promotion in a ' + cat.toLowerCase(),
    ok
      ? 'The gap is small enough that the promotion arrow reaches the conduction band. Once an electron occupies conduction-band states, it can help carry current.'
      : 'The gap is too large for the shown promotion energy, so the arrow stalls before the conduction band. Electrons remain in the valence band and the material conducts poorly.'
  );
}

function togglePanelDynamicForStep() {
  panels[1].dynamic = true;
  state.selected = 1;
}

var demoSteps = [
  {
    title: 'Start with a semiconductor-sized gap',
    narration: 'The valence band is filled below and the conduction band is above it. With a moderate band gap, some electrons can be promoted under suitable conditions, so the material is labeled as a semiconductor.',
    state: { bandGapSize: 1.5 }
  },
  {
    title: 'Shrink the gap toward a conductor',
    narration: 'Drag the conduction band downward until the white gap becomes very small. The label changes to conductor because electrons need little or no extra energy to reach conducting states.',
    state: { bandGapSize: 0.1 }
  },
  {
    title: 'Widen the gap toward an insulator',
    narration: 'Drag the conduction band upward to create a large white separation. The label changes to insulator because ordinary electron promotion energy is not enough to bridge the gap.',
    state: { bandGapSize: 3.5 }
  },
  {
    title: 'Test electron promotion',
    narration: 'Click a material panel to launch an electron-promotion arrow. The arrow crosses a small gap but stalls or fades in a large gap, connecting the visual separation to conductivity.',
    state: { bandGapSize: 3.5 }
  }
];

function applyStep(n) {
  state.step = Math.max(0, Math.min(demoSteps.length - 1, n));
  var step = demoSteps[state.step];
  if (step.state && typeof step.state.bandGapSize === 'number') {
    var input = document.getElementById('bandGapSizeInput');
    var out = document.getElementById('bandGapSizeVal');
    input.value = step.state.bandGapSize;
    out.value = step.state.bandGapSize;
    state.gap = step.state.bandGapSize;
  }
  togglePanelDynamicForStep();
  state.lastPromotion = state.step === 3;
  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (state.step + 1) + '/' + demoSteps.length + ': ' + step.title;
  renderPanels();
}

function nextStep() {
  applyStep((state.step + 1) % demoSteps.length);
}

function prevStep() {
  applyStep((state.step - 1 + demoSteps.length) % demoSteps.length);
}

draw.on('mousemove', function (e) {
  showTooltip('Energy increases upward. The white space is the band gap electrons must cross.', e);
});
draw.on('mouseleave', function () { hideTooltip(); });

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Electrical conductivity in solids depends on the size of the energy band gap between the filled valence band and the empty conduction band.
KEY INSIGHT (what students should walk away understanding): The same valence and conduction bands can describe conductors, semiconductors, and insulators; what changes is the size of the energy gap electrons must overcome.
DEMO STEPS: 4 guided steps — implement the step player in #ui

