  var inset = 4;
  parent.line(x, yTop + inset, x, yBottom - inset)
    .stroke({ color: color, width: 2.4, linecap: 'round' });
  arrowHead(parent, x, yTop + inset, 'up', color, 1);
  arrowHead(parent, x, yBottom - inset, 'down', color, 1);
}

function drawPromotionArrow(parent, x, yStart, yEnd, color, opacity) {
  parent.line(x, yStart, x, yEnd)
    .stroke({ color: color, width: 3.2, linecap: 'round', opacity: opacity });
  arrowHead(parent, x, yEnd, 'up', color, 1.1).opacity(opacity);
}

function drawPanel(i) {
  var p = panels[i];
  var gapPx = panelGapPx(i);
  var cY = conductionY(gapPx);
  var x = p.x;
  var titleY = Math.max(23, cY - 27);

  var hit = interactionLayer.rect(bandW + 56, bandH * 2 + Math.max(18, gapPx) + 62)
    .move(x - 28, Math.max(0, titleY - 28))
    .fill({ color: '#ffffff', opacity: 0 });
  hit.css('cursor', 'pointer')
    .on('mousemove', function (e) {
      showTooltip('Click this material to test whether an electron can cross its band gap.', e);
    })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      state.selected = i;
      state.showPromotion = true;
      render();
      explainPromotion(i);
    });

  geometryLayer.rect(bandW, bandH).move(x, cY).fill(green).stroke('none');
  geometryLayer.rect(bandW, bandH).move(x, valenceY).fill(violet).stroke('none');

  if (gapPx > 5) {
    geometryLayer.line(x, cY + bandH, x, valenceY)
      .stroke({ color: dash, width: 2 }).attr('stroke-dasharray', '8 8');
    geometryLayer.line(x + bandW, cY + bandH, x + bandW, valenceY)
      .stroke({ color: dash, width: 2 }).attr('stroke-dasharray', '8 8');
  }

  addText(labelLayer, panelTitle(i), x + bandW / 2, titleY, 24, '700', 'middle', false);
  addText(labelLayer, 'Conduction', x + bandW / 2, cY + bandH / 2, 24, 'normal', 'middle', false);
  addText(labelLayer, 'Valence', x + bandW / 2, valenceY + bandH / 2, 24, 'normal', 'middle', false);

  if (i === 2 || gapPx <= 8) {
    addText(labelLayer, 'Band gap', x + bandW + 13, valenceY + 4, 24, 'normal', 'start', true);
  } else {
    var ax = x + 47;
    drawDoubleArrow(geometryLayer, ax, cY + bandH, valenceY, ink);
    addText(labelLayer, 'Band gap', ax + 10, (cY + bandH + valenceY) / 2, 24, 'normal', 'start', true);
  }

  if (state.showPromotion && state.selected === i) {
    drawPromotion(i, x, cY, gapPx);
  }
}

function drawPromotion(i, x, cY, gapPx) {
  var gapUnits = panelGapUnits(i);
  var enough = gapUnits <= availableEnergyGapUnits;
  var electronX = x + bandW / 2 - 32;
  var electronY = valenceY + bandH / 2;
  var arrowX = electronX + 32;

  geometryLayer.circle(14).center(electronX, electronY)
    .fill(electronBlue)
    .stroke({ color: '#ffffff', width: 2 });
  addText(labelLayer, 'e⁻', electronX + 15, electronY - 16, 15, '700', 'start', true);

  if (enough) {
    var endY = cY + bandH / 2;
    drawPromotionArrow(geometryLayer, arrowX, electronY - 8, endY + 12, energyGold, 0.95);
    geometryLayer.circle(30).center(arrowX, endY).fill({ color: energyGold, opacity: 0.25 }).stroke('none');
    geometryLayer.circle(14).center(arrowX, endY)
      .fill(electronBlue)
      .stroke({ color: '#ffffff', width: 2 });
  } else {
    var stalledY = valenceY - Math.max(28, gapPx * 0.55);
    stalledY = Math.max(cY + bandH + 15, stalledY);
    drawPromotionArrow(geometryLayer, arrowX, electronY - 8, stalledY, failRed, 0.62);
    geometryLayer.circle(24).center(arrowX, stalledY).fill({ color: failRed, opacity: 0.22 }).stroke('none');
  }
}

function explainPromotion(i) {
  var g = panelGapUnits(i);
  var cat = categoryFromGap(g).toLowerCase();
  if (g <= availableEnergyGapUnits) {
    showPopup(
      'Electron promotion in a ' + cat,
      'The available energy is enough to move the electron from the valence band into the conduction band. Once electrons occupy conduction-band states, they can help carry current.'
    );
  } else {
    showPopup(
      'Electron promotion in an insulator',
      'The band gap is too large for the shown promotion energy. The electron remains below the conduction band, so few charge carriers are available for current.'
    );
  }
}

function render() {
  clearAll();
  for (var i = 0; i < panels.length; i++) drawPanel(i);
}

function update_bandGapSize(v) {
  state.gap = v;
  state.selected = 1;
  state.showPromotion = false;
  render();
}

function trigger_promoteElectron() {
  state.showPromotion = true;
  render();
  explainPromotion(state.selected);
}

var demoSteps = [
  {
    title: 'Start with a semiconductor-sized gap',
    narration: 'The valence band is filled below and the conduction band is above it. With a moderate band gap, some electrons can be promoted under suitable conditions, so the material is labeled as a semiconductor.',
    state: { bandGapSize: 1.5, showPromotion: false }
  },
  {
    title: 'Shrink the gap toward a conductor',
    narration: 'Drag the conduction band downward until the white gap becomes very small. The label changes to conductor because electrons need little or no extra energy to reach conducting states.',
    state: { bandGapSize: 0.1, showPromotion: false }
  },
  {
    title: 'Widen the gap toward an insulator',
    narration: 'Drag the conduction band upward to create a large white separation. The label changes to insulator because ordinary electron promotion energy is not enough to bridge the gap.',
    state: { bandGapSize: 3.5, showPromotion: false }
  },
  {
    title: 'Test electron promotion',
    narration: 'Click a material panel to launch an electron-promotion arrow. The arrow crosses a small gap but stalls or fades in a large gap, connecting the visual separation to conductivity.',
    state: { bandGapSize: 3.5, showPromotion: true }
  }
];

function applyStep(n) {
  state.step = Math.max(0, Math.min(demoSteps.length - 1, n));
  var step = demoSteps[state.step];
  var v = step.state.bandGapSize;
  state.gap = v;
  state.selected = 1;
  state.showPromotion = !!step.state.showPromotion;

  var input = document.getElementById('bandGapSizeInput');
  var out = document.getElementById('bandGapSizeVal');
  if (input) input.value = v;
  if (out) out.value = v;

  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (state.step + 1) + '/' + demoSteps.length + ': ' + step.title;
  render();
}

function nextStep() {
  applyStep((state.step + 1) % demoSteps.length);
}

function prevStep() {
  applyStep((state.step - 1 + demoSteps.length) % demoSteps.length);
}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

